"""### Question 1: Who are the authors of this article and who published this article?"""

# 4. Use a dictionary to hold all three questions from the business analysts
questions = {
    "Question_1": "Who are the authors of this article and who published this article?",
    "Question_2": "List down the three leadership characteristics in bulleted points and explain each one of the characteristics under two lines.",
    "Question_3": "Can you explain specific examples from the article where Apple's approach to leadership has led to successful innovations?"
}

# 5. Specify OpenAI LLM Model to be used.
GENERATION_MODEL = "gpt-4o-mini"

# 6.  Define a function which uses LLM and parameters to generate response for user's questions.
def get_llm_answer(question,
                   param1_temperature=0,
                   param2_top_p=0.95,
                   param3_max_tokens=1000,
                   param4_frequency_penalty=0.5,
                   param5_presence_penalty=0.3):

  # Using .with_raw_response bypasses the broken parsing layer entirely
  raw_response = client.chat.completions.with_raw_response.create(
    model=GENERATION_MODEL,
    messages=[{"role": "user", "content": question}],
    temperature=param1_temperature,  # randomness; max=2; <1 is less random and more relevant; >1 more random and can produces incoherent output; =0 always picks the single highest-probability token.
    top_p=param2_top_p, # diversity; max is 1; closer to 1 like 0.9, 0.95, more diverse tokens with lower probabilities are included for the model to considers until the total sum is equal to the value of top_p.
    max_tokens=param3_max_tokens,   # caps the number of tokens the model generates in its response.
    frequency_penalty=param4_frequency_penalty,    # range: -2.0 to 2.0; default=0; reduces the probability of a token proportionally to how many times it has already appeared in the output. The more a token has been used, the more it's penalized. A value of 0.5 is a reasonable starting point for long-form content.
    presence_penalty=param5_presence_penalty # range: -2.0 to 2.0; default =0; applies a flat penalty to any token that has appeared at least once, regardless of how many times. It discourages repetition of any previously used word, pushing the model toward novel vocabulary.

  )

  # Manually parse the JSON string response
  response_data = json.loads(raw_response.text)
  return response_data['choices'][0]['message']['content']

# 7. LLM answer for question 1 using three temperation values: 0.1, 1, 2 and top_p = 0.95 close to the max value.  It is known that low temperature like 0.1 combined with high top_p result in best logical LLM answers.

