# 20. Initialize a text splitter that uses OpenAI's token encoder
text_splitter = RecursiveCharacterTextSplitter.from_tiktoken_encoder(
    encoding_name='cl100k_base',                                                # Using the mean, min metrics from the Basic descriptive statistical summaries in code cell 'Data Overview', the chunk_size is determined to be best 1000 and chunk_overlap to be 200.  This however, is not static for every document so an analysis of data overview is a must to determine the chunk_size and chunk_overlap and this should be automated in incorporated into the final application.
    # Each chunk will have up to 1000 tokens
    chunk_size=1000,                                                             # 200 tokens will overlap between consecutive chunks (for context continuity)
    chunk_overlap=200
)

# 21. Use the text splitter to divide the PDF content into smaller chunks
document_chunks = pdf_loader.load_and_split(text_splitter)                      # Returns a list of chunked documents

