# Check and print the dimension (length) of the embedding vector
print("Dimension of the embedding vector ", len(embedding_1))                   # Typically 1536 or 2048 depending on model
# Embedding all chunks
embedding_all = embedding_model.embed_documents([doc.page_content for doc in document_chunks])

"""### Vector Database"""

# 25. Create or load the persistent vector store
out_dir = "external_pdf_content_db"

if os.path.exists(out_dir) and os.listdir(out_dir):
    # Load the existing vector store
    vectorstore = Chroma(
        persist_directory=out_dir,
        embedding_function=embedding_model
    )
    print("Existing vector store loaded successfully.")

else:
    # Create the vector store and persist it to disk
    vectorstore = Chroma.from_documents(
        document_chunks,
        embedding_model,
        persist_directory=out_dir
    )
    print("New vector store created and saved successfully.")

"""### Retriever"""

# 26. Given user input, this Retriever queries vector database to find k most relevant vectors from the Chroma vector database.

def get_relevant_chunks(user_input, k=3):
    retriever = vectorstore.as_retriever(search_kwargs={"k": k}) #k is retriever output number.
    relevant_document_chunks = retriever.invoke(user_input)

    context_list = []
    for d in relevant_document_chunks:
        source = d.metadata.get("source", "Unknown source")
        page = d.metadata.get("page", "Unknown page")
        page_display = page + 1 if isinstance(page, int) else page
        chunk_with_citation = f"[Source: {source} | Page: {page_display}]\n{d.page_content}"
        context_list.append(chunk_with_citation)

    # return context for query
    context_for_query = "\n\n---\n\n".join(context_list)

    return context_for_query

"""### Response Function"""

# 27. Define the system prompt for the model
qna_system_message = """
### ROLE
You are an AI assistant to business analysts who have to look into large volume of business documents to extract insights of a business.  Your task is to assist business analysts and help them quickly get the insight from the context provided by the business analyst.

### CONTEXT
User input will include the necessary context for you to answer their questions. This context will begin with the token: ###Context. The context contains references to specific portions of the research article relevant to the query, along with their source details.

### TASK
When crafting your response:
1. Use only the provided context to answer the question.
2. Answer with concise and factual information or insights.
3. Include the source reference with the page number, article name, authors, publishers, year of publication.
4. If no information is found to answer the context, respond with: "Sorry, this is out of my knowledge base."

### GUIDELINES
- Provide clear, direct answers using only the given context.
- Do not include any additional information outside of the context.
- If no relevant information is found to answer the context, respond with: "Sorry, this is out of my knowledge base."

### OUTPUT FORMAT
Here is an example of how to structure your response:

Answer:
[Answer for your question]

Source:
[Source details with page or section]
"""

# 28. Define the user message template
qna_user_message_template = """

###Context
{context}

###Question
{question}
"""

# 29. Define a function to generate answer with the use of RAG


def generate_rag_response(user_input,
                          k=3,                           # parameter for Chroma vector db method .as_retriever; this controls output number of the retriever.
                          param1_temperature=0,          # control randomness of LLM response.
                          param2_top_p=0.95, # control diversity of LLM response
                          param3_max_tokens=1000,
                          param4_frequency_penalty=0.5,  # reduces the probability of a token proportionally to how many times it has already appeared in the output
                          param5_presence_penalty=0.3):  # applies a flat penalty to any token that has appeared at least once, regardless of how many times.


    global qna_system_message, qna_user_message_template

    context_for_query = get_relevant_chunks(user_input, k)


    # Add the context in the prompt
    user_message = qna_user_message_template.replace('{context}', context_for_query)
    user_message = user_message.replace('{question}', user_input)

    # Generate response using LLM;
    # Note that the previously-defined function response has the signature with several parameters in order like below:
    #response(system_prompt, userinput,temperature, top_p, max_tokens, frequency_penalty, presence_penalty)

    try:
        llm_response_content = globals()['response'](qna_system_message, user_message,param1_temperature, param2_top_p,param3_max_tokens)

    except Exception as e:
        llm_response_content = f'Sorry, I encountered the following error: \n {e}'

    return llm_response_content, context_for_query

